export function seatPositions(table) {
  const [width,height]=tableSize(table);
  if(table.shape==='round')return Array.from({length:table.seats},(_,i)=>{const angle=2*Math.PI*i/table.seats-Math.PI/2;return {x:Math.round((width/2+25)*Math.cos(angle)),y:Math.round((height/2+25)*Math.sin(angle))};});
  if(table.shape==='square')return Array.from({length:table.seats},(_,i)=>{const angle=2*Math.PI*i/table.seats-Math.PI/4;const scale=(Math.max(width,height)/2+24)/Math.max(Math.abs(Math.cos(angle)),Math.abs(Math.sin(angle)));return {x:Math.round(scale*Math.cos(angle)),y:Math.round(scale*Math.sin(angle))};});
  if(table.shape==='sweetheart')return Array.from({length:table.seats},(_,i)=>({x:Math.round(-width/2+(i+1)*width/(table.seats+1)),y:Math.round(-height/2-22)}));
  const top=Math.ceil((table.seats-2)/2),bottom=Math.floor((table.seats-2)/2);
  const half=width/2;
  return [
    ...Array.from({length:top},(_,i)=>({x:Math.round(-half+(i+1)*width/(top+1)),y:Math.round(-height/2-22)})),
    {x:Math.round(half+22),y:0},
    ...Array.from({length:bottom},(_,i)=>({x:Math.round(-half+(i+1)*width/(bottom+1)),y:Math.round(height/2+22)})),
    {x:Math.round(-half-22),y:0}
  ];
}
function tableSize(table){
  if(table.widthInches&&table.depthInches)return [Math.max(table.shape==='round'||table.shape==='square'||table.shape==='sweetheart'?70:Math.ceil((table.seats-2)/2)*24+32,Math.min(300,Math.round(table.widthInches*1.35))),Math.max(48,Math.min(130,Math.round(table.depthInches*1.35)))];
  if(table.shape==='round')return [72,72];
  if(table.shape==='square')return [82,82];
  if(table.shape==='sweetheart')return [100,60];
  return [Math.max(120,Math.ceil((table.seats-2)/2)*23+32),64];
}

function planBoard(plan,esc,lang,readOnly=false) {
  const w=words[lang];
  return `<svg id="seating-board" viewBox="0 0 1000 700" role="img" aria-label="${w.visual}" xmlns="http://www.w3.org/2000/svg"><defs><pattern id="seat-grid" width="25" height="25" patternUnits="userSpaceOnUse"><path class="planner-grid-path" d="M 25 0 L 0 0 0 25" fill="none" stroke="currentColor" stroke-width="1"/></pattern></defs><rect class="planner-board-base" width="1000" height="700"/>${plan.floorPlan?`<image href="/api/plans/${plan.id}/floor-plan/${plan.floorPlan.id}" x="0" y="0" width="1000" height="700" preserveAspectRatio="xMidYMid meet"/><rect width="1000" height="700" fill="#fff" opacity=".22"/>`:''}<rect class="planner-grid-layer" width="1000" height="700" fill="url(#seat-grid)" pointer-events="none"/>${plan.floorPlan?.meters>0?`<g class="planner-scale"><line x1="${plan.floorPlan.points[0].x}" y1="${plan.floorPlan.points[0].y}" x2="${plan.floorPlan.points[1].x}" y2="${plan.floorPlan.points[1].y}"/><circle cx="${plan.floorPlan.points[0].x}" cy="${plan.floorPlan.points[0].y}" r="5"/><circle cx="${plan.floorPlan.points[1].x}" cy="${plan.floorPlan.points[1].y}" r="5"/><text x="${Math.round((plan.floorPlan.points[0].x+plan.floorPlan.points[1].x)/2)}" y="${Math.round((plan.floorPlan.points[0].y+plan.floorPlan.points[1].y)/2)-10}" text-anchor="middle">${plan.floorPlan.meters} m</text></g>`:''}${(plan.features||[]).map(item=>`<g class="planner-feature" data-feature-id="${item.id}" transform="translate(${item.x} ${item.y})" ${readOnly?'':'tabindex="0"'} role="group" aria-label="${esc(item.label||w[item.kind])}, ${w.position}"><rect class="planner-feature-body planner-feature-${item.kind}" x="-${item.width/2}" y="-${item.height/2}" width="${item.width}" height="${item.height}" rx="12"/><text text-anchor="middle" dominant-baseline="middle" pointer-events="none">${esc(item.label||w[item.kind])}</text></g>`).join('')}${plan.tables.map(table=>{
    const positions=seatPositions(table),names=new Map(plan.guests.map(g=>[g.id,g]));
    const [width,height]=tableSize(table),tableBody=table.shape==='round'?`<circle r="${width/2}" class="planner-table-body"/>`:table.shape==='serpentine'?`<path d="M ${-width/2} ${-height/2} Q ${-width/4} ${-height/2-15} 0 ${-height/2} T ${width/2} ${-height/2} L ${width/2} ${height/2} Q ${width/4} ${height/2+15} 0 ${height/2} T ${-width/2} ${height/2} Z" class="planner-table-body"/>`:`<rect x="${-width/2}" y="${-height/2}" width="${width}" height="${height}" rx="${table.shape==='sweetheart'?height/2:table.shape==='square'?6:9}" class="planner-table-body"/>`;
    return `<g class="planner-table" data-table-id="${table.id}" transform="translate(${table.x} ${table.y})" ${readOnly?'':'tabindex="0"'} role="group" aria-label="${esc(`${table.label}, ${w.position}`)}">${tableBody}<text class="planner-table-label" text-anchor="middle" dominant-baseline="middle" pointer-events="none">${esc(table.label)}</text>${positions.map(({x,y},index)=>{const guest=names.get(table.assignments[index]);return `<g class="planner-seat ${guest?'is-assigned':''} ${guest?`meal-${guest.meal}`:''}" ${readOnly?'':`data-action="select-seat" data-table="${table.id}" data-index="${index}" tabindex="0" role="button"`} aria-label="${esc(`${table.label}, ${w.seats} ${index+1}: ${guest?.name||w.unassigned}`)}"><circle cx="${x}" cy="${y}" r="12"/><text x="${x}" y="${y}" text-anchor="middle" dominant-baseline="middle" pointer-events="none">${guest?esc(guest.name.slice(0,2).toUpperCase()):'+'}</text></g>`;}).join('')}</g>`;
  }).join('')}</svg>`;
}

function tableEditor(table,w,esc){
  const shapes=['round','rect','long','square','sweetheart','serpentine'];
  return `<details class="planner-table-row"><summary>${esc(table.label)} <small>${w[table.shape]} · ${table.seats} ${w.seats}</small></summary><form class="planner-table-form" data-id="${table.id}"><label>${w.tableName}<input name="label" maxlength="30" required value="${esc(table.label)}"></label><label>${w.shape}<select name="shape">${shapes.map(shape=>`<option value="${shape}" ${table.shape===shape?'selected':''}>${w[shape]}</option>`).join('')}</select></label><label>${w.seats}<input name="seats" type="number" min="2" max="20" required value="${table.seats}"></label><div class="planner-coordinates"><label>${w.widthInches}<input name="widthInches" type="number" min="24" max="240" required value="${table.widthInches||72}"></label><label>${w.depthInches}<input name="depthInches" type="number" min="24" max="120" required value="${table.depthInches||36}"></label></div><div class="planner-coordinates"><label>X<input name="x" type="number" min="55" max="945" required value="${table.x}"></label><label>Y<input name="y" type="number" min="55" max="645" required value="${table.y}"></label></div><div class="planner-inline"><button class="button" type="submit">${w.save}</button><button class="button button-outline" type="button" data-action="planner-remove-table" data-id="${table.id}">${w.remove}</button></div></form></details>`;
}

function featureEditor(item,w,esc){
  const kinds=['stage','dance','buffet','entrance','aisle','screen'];
  return `<details class="planner-table-row"><summary>${esc(item.label||w[item.kind])} <small>${w[item.kind]}</small></summary><form class="planner-feature-form planner-table-form" data-id="${item.id}"><label>${w.featureName}<input name="label" maxlength="40" value="${esc(item.label)}"></label><label>${w.kind}<select name="kind">${kinds.map(kind=>`<option value="${kind}" ${kind===item.kind?'selected':''}>${w[kind]}</option>`).join('')}</select></label><div class="planner-coordinates"><label>X<input name="x" type="number" min="0" max="1000" required value="${item.x}"></label><label>Y<input name="y" type="number" min="0" max="700" required value="${item.y}"></label></div><div class="planner-coordinates"><label>${w.width}<input name="width" type="number" min="40" max="250" required value="${item.width}"></label><label>${w.height}<input name="height" type="number" min="40" max="200" required value="${item.height}"></label></div><div class="planner-inline"><button class="button" type="submit">${w.save}</button><button class="button button-outline" type="button" data-action="planner-remove-feature" data-id="${item.id}">${w.remove}</button></div></form></details>`;
}

function sharePanel(plan,members,w,esc){
  if(plan.access!=='OWNER')return '';
  return `<section class="form-panel plan-share"><h2>${w.share}</h2><p class="fine-print">${w.shareHelp}</p><form id="plan-share-form" class="plan-inline-form"><label>${w.email}<input name="email" type="email" maxlength="254" autocomplete="email" required></label><label>${w.share}<select name="permission"><option value="VIEW">${w.viewer}</option><option value="EDIT">${w.editor}</option></select></label><button class="button" type="submit">${w.invite}</button></form><div class="plan-inline-form"><a class="button button-outline" href="#/plans/${plan.id}?view=presentation">${w.openPresentation}</a><button class="button button-outline" type="button" data-action="planner-copy-presentation">${w.copyPresentation}</button></div><p class="fine-print">${w.localPresentationLink}</p><p id="presentation-link-status" class="fine-print" role="status"></p>${members?.items?.map(member=>`<form class="plan-member-form plan-inline-form" data-id="${member.id}" data-version="${member.version}"><span>${esc(member.email)}</span><label>${w.share}<select name="permission"><option value="VIEW" ${member.permission==='VIEW'?'selected':''}>${w.viewer}</option><option value="EDIT" ${member.permission==='EDIT'?'selected':''}>${w.editor}</option></select></label><button class="button button-outline" type="submit" name="action" value="update">${w.save}</button><button class="button button-outline" type="submit" name="action" value="remove">${w.remove}</button></form>`).join('')||''}<p id="share-error" role="alert" class="form-error" hidden></p></section>`;
}

function inquirySection(plan,inquiries,w,esc,lang){
  const ready=inquiries?.planId===plan.id && !inquiries.error;
  const linked=ready?plan.links.map(link=>inquiries.items.find(item=>item.kind===link.kind&&item.id===link.id)||{...link,missing:true}):[];
  const available=ready?inquiries.options.filter(item=>!plan.links.some(link=>link.kind===item.kind&&link.id===item.id)):[];
  const name=item=>typeof item.name==='string'?item.name:item.name?.[lang]||item.name?.en||w.unavailableInquiry;
  const label=item=>`${name(item)}${item.packageName?' · '+name({name:item.packageName}):''}`;
  const status=item=>w[`${item.status?.toLowerCase()}Inquiry`]||w.unavailableInquiry;
  return `<section class="form-panel"><h2>${w.eventTeam}</h2><p class="fine-print">${w.teamHelp}</p>${plan.access==='VIEW'?'':`<button class="button button-outline" type="button" data-action="planner-refresh-inquiries">${w.refreshInquiries}</button>`}${!ready?`<p role="status">${inquiries?.error?w.inquiriesError:w.inquiriesLoading}</p>`:linked.length?`<ul class="plan-item-list">${linked.map(item=>`<li class="plan-list-row"><span><strong>${esc(item.missing?w.unavailableInquiry:label(item))}</strong><small>${w[item.kind==='venue'?'venueInquiry':'serviceInquiry']} · ${item.date?esc(item.date)+' · ':''}${item.missing?w.unavailableInquiry:status(item)}${item.status==='OFFERED'&&item.quote?` · ${w.quotedPrice}: ${new Intl.NumberFormat(lang==='ar'?'ar-EG':'en-EG').format(item.quote)} EGP`:''}</small></span><span class="plan-row-actions">${!item.missing?`<a class="button button-outline" href="${item.kind==='venue'?`#/conversation/${item.id}`:'#/services/requests'}">${w.openInquiry}</a>`:''}${plan.access==='OWNER'?`<button class="button button-outline" type="button" data-action="planner-unlink-inquiry" data-kind="${item.kind}" data-id="${item.id}">${w.unlinkInquiry}</button>`:''}</span></li>`).join('')}</ul>`:`<p>${w.noLinked}</p>`}${ready&&plan.access==='OWNER'?(plan.links.length>=30?`<p class="fine-print">${w.linkLimit}</p>`:available.length?`<form id="plan-inquiry-form" class="plan-inline-form"><label>${w.chooseInquiry}<select name="inquiry" required>${available.map(item=>`<option value="${item.kind}:${item.id}">${w[item.kind==='venue'?'venueInquiry':'serviceInquiry']} · ${esc(label(item))}${item.date?' · '+esc(item.date):''}</option>`).join('')}</select></label><button class="button" type="submit">${w.linkInquiry}</button></form>`:`<p class="fine-print">${inquiries.options.length?w.allLinked:w.noInquiries} <a href="#/services">${w.serviceInquiry}</a> · <a href="#/discover">${w.venueInquiry}</a></p>`):''}</section>`;
}

function planOverview(plan,w,esc,lang,inquiries){
  const number=n=>new Intl.NumberFormat(lang==='ar'?'ar-EG':'en-EG').format(n),total=plan.expenses.reduce((n,x)=>n+x.amount,0),paid=plan.expenses.filter(x=>x.paid).reduce((n,x)=>n+x.amount,0);
  const choice=(value,label,selected)=>`<option value="${value}" ${value===selected?'selected':''}>${label}</option>`;
  const remove=(kind,id)=>`<button class="button button-outline" type="button" data-action="planner-remove-item" data-kind="${kind}" data-id="${id}" aria-label="${w.removeItem}">${w.remove}</button>`;
  const toggle=(kind,item,key)=>`<button class="button button-outline" type="button" data-action="planner-toggle-item" data-kind="${kind}" data-id="${item.id}">${w[item[key]?(key==='paid'?'markUnpaid':'markOpen'):(key==='paid'?'markPaid':'markDone')]}</button>`;
  const row=(kind,item,details,key)=>`<li class="plan-list-row"><span><strong>${esc(item.title)}</strong><small>${details}</small></span><span class="plan-row-actions">${key?toggle(kind,item,key):''}${remove(kind,item.id)}</span></li>`;
  const groups=[...new Set(plan.guests.map(g=>g.group).filter(Boolean))];
  const sorted=[...plan.schedule].sort((a,b)=>`${a.date}T${a.time}`.localeCompare(`${b.date}T${b.time}`));
  const day=plan.date?sorted.filter(item=>item.date===plan.date):[];
  const other=sorted.filter(item=>item.date!==plan.date);
  return `<div class="plan-summary"><div class="plan-summary-card"><span class="plan-summary-icon" aria-hidden="true">👥</span><div class="plan-summary-body"><small>${w.totalGuests}</small><strong>${number(plan.guests.length)}</strong></div></div><div class="plan-summary-card is-attending"><span class="plan-summary-icon" aria-hidden="true">✓</span><div class="plan-summary-body"><small>${w.attending}</small><strong>${number(plan.guests.filter(g=>g.rsvp==='yes').length)}</strong></div></div><div class="plan-summary-card is-awaiting"><span class="plan-summary-icon" aria-hidden="true">⏳</span><div class="plan-summary-body"><small>${w.awaiting}</small><strong>${number(plan.guests.filter(g=>g.rsvp==='pending').length)}</strong></div></div><div class="plan-summary-card is-tasks"><span class="plan-summary-icon" aria-hidden="true">☑</span><div class="plan-summary-body"><small>${w.tasks}</small><strong>${number(plan.tasks.filter(x=>x.done).length)} / ${number(plan.tasks.length)}</strong></div></div></div>${plan.access!=='VIEW'&&(!plan.tasks.length||!plan.shopping.length||(plan.date&&!plan.schedule.length))?`<section class="form-panel plan-starter"><span class="planner-kicker">${lang==='ar'?'اقتراحات التجهيز':'SMART SETUP'}</span><h2>${w.quickStart}</h2><p>${w.quickStartHelp}</p><button class="button" type="button" data-action="planner-starter">${w.addStarter}</button></section>`:''}<div class="plan-sections"><section class="form-panel"><span class="planner-kicker">${lang==='ar'?'إدارة الحضور':'GUEST PROTOCOL'}</span><h2>${w.guests}</h2><form id="plan-guest-form" class="plan-inline-form"><label>${w.guestName}<input id="guest-name" name="name" maxlength="100" required></label><label>${w.group}<input name="group" maxlength="60" list="guest-groups" placeholder="${w.groupHint}"></label><datalist id="guest-groups">${groups.map(group=>`<option value="${esc(group)}">`).join('')}</datalist><button class="button" type="submit">${w.addGuest}</button></form>${plan.guests.length?`<div class="plan-guest-list">${plan.guests.map(g=>`<details class="plan-guest-row"><summary><strong>${esc(g.name)}</strong><small>${g.group?`${esc(g.group)} · `:''}${w[g.rsvp==='pending'?'pendingRsvp':g.rsvp]}</small></summary><form class="plan-guest-edit" data-id="${g.id}"><label>${w.guestName}<input name="name" maxlength="100" value="${esc(g.name)}" required></label><label>${w.group}<input name="group" maxlength="60" list="guest-groups" value="${esc(g.group)}"></label><label>${w.rsvp}<select name="rsvp">${[['pending','pendingRsvp'],['yes','yes'],['no','no']].map(([v,key])=>choice(v,w[key],g.rsvp)).join('')}</select></label><label>${w.meal}<select name="meal">${[['none','none'],['standard','standard'],['vegetarian','vegetarian'],['vegan','vegan'],['other','otherMeal']].map(([v,key])=>choice(v,w[key],g.meal)).join('')}</select></label><div class="plan-row-actions"><button class="button" type="submit">${w.saveGuest}</button><button class="button button-outline" type="button" data-action="planner-remove-guest" data-id="${g.id}">${w.remove}</button></div></form></details>`).join('')}</div>`:`<p class="plan-empty-notice">${w.noGuests}</p>`}</section><section class="form-panel"><span class="planner-kicker">${lang==='ar'?'المالية والتعاقدات':'FINANCIAL PROTOCOL'}</span><h2>${w.budget}</h2><p class="fine-print">${w.budgetHelp}</p><form id="plan-budget-form" class="plan-inline-form"><label>${w.budgetLimit}<input name="budget" type="number" min="0" max="1000000000" step="1" value="${plan.budget}" required></label><button class="button" type="submit">${w.save}</button></form><div class="plan-budget-stats"><span>${w.plannedCost}: <strong>${number(total)} EGP</strong></span><span>${w.paidCost}: <strong>${number(paid)} EGP</strong></span><span>${w.remaining}: <strong>${number(plan.budget-total)} EGP</strong></span></div><h3>${w.expense}</h3><form id="plan-expense-form" class="plan-inline-form"><label>${w.expense}<input name="title" maxlength="120" required></label><label>${w.amount}<input name="amount" type="number" min="0" max="1000000000" step="1" required></label><button class="button" type="submit">${w.addExpense}</button></form>${plan.expenses.length?`<ul class="plan-item-list">${plan.expenses.map(item=>row('expenses',item,`${number(item.amount)} EGP${item.paid?` · ${w.paidCost}`:''}`,'paid')).join('')}</ul>`:`<p class="plan-empty-notice">${w.noExpenses}</p>`}</section><section class="form-panel"><span class="planner-kicker">${lang==='ar'?'جدول المهام':'TASK CHECKLIST'}</span><h2>${w.tasks}</h2><form id="plan-task-form" class="plan-inline-form"><label>${w.task}<input name="title" maxlength="120" required></label><label>${w.due}<input name="due" type="date"></label><button class="button" type="submit">${w.addTask}</button></form>${plan.tasks.length?`<ul class="plan-item-list">${plan.tasks.map(item=>row('tasks',item,`${item.due?esc(item.due)+' · ':''}${item.done?w.completed:''}`,'done')).join('')}</ul>`:`<p class="plan-empty-notice">${w.noTasks}</p>`}</section><section class="form-panel"><span class="planner-kicker">${lang==='ar'?'المشتريات والتجهيزات':'ACQUISITIONS'}</span><h2>${w.shopping}</h2><form id="plan-shopping-form" class="plan-inline-form"><label>${w.shoppingItem}<input name="title" maxlength="120" required></label><label>${w.quantity}<input name="quantity" type="number" min="1" max="999" step="1" value="1" required></label><button class="button" type="submit">${w.addShopping}</button></form>${plan.shopping.length?`<ul class="plan-item-list">${plan.shopping.map(item=>row('shopping',item,`${w.quantity}: ${number(item.quantity)}${item.done?` · ${w.completed}`:''}`,'done')).join('')}</ul>`:`<p class="plan-empty-notice">${w.noShopping}</p>`}</section><section class="form-panel"><span class="planner-kicker">${lang==='ar'?'الجدول الزمني ليوم المناسبة':'RUN SHEET'}</span><h2>${w.schedule}</h2><form id="plan-date-form" class="plan-inline-form"><label>${w.eventDate}<input name="date" type="date" value="${esc(plan.date)}"></label><button class="button button-outline" type="submit">${w.saveDate}</button></form><form id="plan-schedule-form" class="plan-inline-form"><label>${w.scheduleItem}<input name="title" maxlength="120" required></label><label>${w.date}<input name="date" type="date" value="${esc(plan.date)}" required></label><label>${w.time}<input name="time" type="time" required></label><button class="button" type="submit">${w.addSchedule}</button></form><h3>${w.eventDay}${plan.date?' · '+esc(plan.date):''}</h3>${!plan.date?`<p class="plan-empty-notice">${w.noEventDate}</p>`:day.length?`<ol class="plan-timeline">${day.map(item=>`<li><time datetime="${esc(item.date)}T${esc(item.time)}">${esc(item.time)}</time><strong>${esc(item.title)}</strong>${remove('schedule',item.id)}</li>`).join('')}</ol>`:`<p class="plan-empty-notice">${w.noEventDay}</p>`}${other.length?`<h3>${w.otherDates}</h3><ul class="plan-item-list">${other.map(item=>row('schedule',item,`${esc(item.date)} · ${esc(item.time)}`)).join('')}</ul>`:''}</section>${inquirySection(plan,inquiries,w,esc,lang)}</div><p id="planner-error" role="alert" class="form-error" hidden></p>`;
}

export function originalRoomSection(lang) {
  const w=words[lang];
  const isAr = lang === 'ar';
  return `<section class="room-3d room-3d-hero" data-original-room>
    <div class="room-3d-viewport-stage">
      <div class="room-3d-canvas" role="group" aria-label="${w.originalRoom}"></div>
      <p class="room-3d-status" role="status">${w.threeDLoading}</p>
    </div>
    <aside class="room-3d-cockpit" aria-label="${isAr ? 'خيارات الجولة والتحكم' : 'Tour Options & Controls'}">
      <div class="room-3d-cockpit-header">
        <span class="room-3d-cockpit-kicker">${isAr ? 'المشهد الافتراضي النموذجي' : 'SPATIAL PROTOTYPE'}</span>
        <h2>${w.originalRoom}</h2>
        <p>${w.originalRoomHelp}</p>
      </div>
      <div class="room-3d-cockpit-section">
        <span class="room-3d-cockpit-label">${isAr ? 'زاوية الكاميرا والتحكم' : 'Camera & Viewport'}</span>
        <div class="room-3d-controls room-3d-view-controls">
          <button class="button button-outline" type="button" data-scene-view="perspective">${w.perspective}</button>
          <button class="button button-outline" type="button" data-scene-view="top">${w.top}</button>
          <button class="button button-outline" type="button" data-scene-zoom="in">${w.zoomIn}</button>
          <button class="button button-outline" type="button" data-scene-zoom="out">${w.zoomOut}</button>
          <button class="button button-outline" type="button" data-scene-sound aria-pressed="false">${isAr?'الصوت':'Sound'}</button>
          <button class="button button-outline" type="button" data-scene-fullscreen>${isAr?'ملء الشاشة':'Fullscreen'}</button>
        </div>
      </div>
      <div class="room-3d-cockpit-section">
        <span class="room-3d-cockpit-label">${isAr ? 'أجواء الإضاءة' : 'Atmosphere'}</span>
        <div class="room-3d-controls room-3d-atmo-controls">
          ${['golden','sunrise','midnight'].map(mode=>`<button class="button button-outline" type="button" data-scene-atmosphere="${mode}" aria-pressed="${mode==='golden'}">${w[mode]}</button>`).join('')}
        </div>
      </div>
      <p class="fine-print">${w.modelCredit}: <a href="https://sketchfab.com/3d-models/rec-room-wedding-2983d1e21f3f4037a3c3354187a160c2" target="_blank" rel="noopener noreferrer">Rec Room - Wedding</a> by Lol_o9 · <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noopener noreferrer">CC BY 4.0</a>.</p>
    </aside>
  </section>`;
}

function presentationView(plan,w,esc,lang){
  const assigned=plan.tables.reduce((total,table)=>total+table.assignments.filter(Boolean).length,0);
  const names=new Map(plan.guests.map(guest=>[guest.id,guest.name]));
  return `<section class="plan-presentation"><div class="plan-presentation-heading"><div><h2>${w.presentation}</h2><p>${w.presentationHelp}</p></div><button class="button" type="button" data-action="planner-print">${w.presentationPrint}</button></div><div class="plan-presentation-facts"><span>${w.tables}: <strong>${plan.tables.length}</strong></span><span>${w.totalGuests}: <strong>${plan.guests.length}</strong></span><span>${w.assigned}: <strong>${assigned}</strong></span></div>${plan.tables.length?`<div class="planner-main">${planBoard(plan,esc,lang,true)}</div>`:`<p class="form-panel">${w.presentationEmpty}</p>`}<p class="fine-print">${w.presentationGuestsHelp}</p>${assigned?`<details class="plan-presentation-guests"><summary>${w.presentationGuests}</summary><div class="plan-presentation-guest-grid">${plan.tables.filter(table=>table.assignments.some(Boolean)).map(table=>`<section><h3>${esc(table.label)}</h3><ol>${table.assignments.map((id,index)=>id?`<li>${w.seatNumber} ${index+1}: ${esc(names.get(id)||'')}</li>`:'').join('')}</ol></section>`).join('')}</div></details>`:''}</section>`;
}

export function planningView({items,plan,loaded,error,account,lang,escape:esc,selectedSeat,scaleMode=false,scalePoints=[],view,members,inquiries,history,suggestion,suggestedLayout,picker=false,pickerCategory='rect',inspector='',zoom=1,gridVisible=true,ceremonyMode='block',ceremonySeat='',guestSelected='',guestForm=false,taskFilter='all',createModal=false}) {
  const w=words[lang];
  if(!account)return `<section class="page-title"><h1>${w.title}</h1><p>${w.signin}</p><a class="button" href="#/account">${lang==='ar'?'سجّل دخول':'Sign in'}</a></section>`;
  if(!loaded)return `<p role="status">${lang==='ar'?'جاري التحميل…':'Loading plans…'}</p>`;
  if(error)return `<p role="alert">${w.error}</p>`;
  if(!plan) {
    const isAr = lang === 'ar';
    const num = n => new Intl.NumberFormat(lang === 'ar' ? 'ar-EG' : 'en-EG').format(n);
    return `<div class="planner-dashboard">
      <section class="page-title planner-hero">
        <div class="planner-hero-inner">
          <div class="planner-hero-text">
            <span class="planner-kicker">${isAr ? 'المخطط المكاني والفعاليات الملكية' : 'SOVEREIGN SPATIAL & EVENT PLANNER'}</span>
            <h1>${w.title}</h1>
            <p class="planner-hero-intro">${w.intro}</p>
          </div>
          <div class="planner-hero-actions">
            <button class="button planner-create-hero-btn" type="button" data-action="planner-open-create">
              <span aria-hidden="true">+</span>
              <span>${isAr ? 'إنشاء مناسبة جديدة' : 'Create New Event'}</span>
            </button>
          </div>
        </div>
      </section>

      <div class="planner-events-section">
        <div class="planner-events-head">
          <div class="planner-events-title-wrap">
            <h2>${isAr ? 'مناسباتي المسجلة' : 'My Sovereign Events'}</h2>
            <span class="planner-events-count-badge">${num(items.length)} ${isAr ? (items.length === 1 ? 'مناسبة' : 'مناسبات') : (items.length === 1 ? 'event' : 'events')}</span>
          </div>
        </div>

        <div class="planner-list">
          ${items.length ? items.map(item=>`<a class="planner-event" href="#/plans/${item.id}?view=seating"><span class="planner-event-icon" aria-hidden="true">${item.type==='wedding'?'💍':item.type==='conference'?'🏛️':'✨'}</span><span class="planner-event-info"><strong>${esc(item.name)}</strong><small><span class="planner-event-tag">${w[item.type]}</span>${item.date?' · 📅 '+esc(item.date):''}${item.access!=='OWNER'?' · '+w.shared:''}</small></span><span class="planner-event-cta">${w.open} <span aria-hidden="true">›</span></span></a>`).join('') : `<div class="planner-empty"><span class="planner-empty-icon" aria-hidden="true">🏛️</span><h3>${isAr ? 'لا توجد مناسبات بعد' : 'No Events Created Yet'}</h3><p>${w.empty}</p><button class="button" type="button" data-action="planner-open-create">+ ${w.new}</button></div>`}
        </div>
      </div>

      <!-- Event Creator Modal Dialog (Stuck to page, opens on click) -->
      <div class="planner-create-modal-layer${createModal ? ' is-open' : ''}" ${createModal ? '' : 'hidden'}>
        <div class="planner-create-backdrop" data-action="planner-close-create" tabindex="-1"></div>
        <div class="planner-create-dialog" role="dialog" aria-modal="true" aria-labelledby="planner-modal-title">
          <button class="planner-create-close" type="button" data-action="planner-close-create" aria-label="${isAr ? 'إغلاق' : 'Close'}">
            <svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M18 6 6 18M6 6l12 12"/></svg>
          </button>
          <div class="planner-create-modal-header">
            <span class="planner-kicker">${isAr ? 'إنشاء خطة جديدة' : 'NEW EVENT PROTOCOL'}</span>
            <h2 id="planner-modal-title">${w.new}</h2>
            <p class="planner-create-modal-desc">${isAr ? 'ابدأ بتنظيم مناسبتك الملكية، ورتب الضيوف والميزانية والتوزيع المكاني بدقة متناهية.' : 'Begin drafting your sovereign event, organize seating, budget, and ceremonial flow with precision.'}</p>
          </div>
          <form id="plan-create-form" class="planner-create-modal-form">
            <div class="form-grid">
              <div class="form-field full-width">
                <label for="plan-name">${w.eventName}</label>
                <input id="plan-name" name="name" maxlength="100" placeholder="${isAr ? 'مثال: حفل زفاف قصر عابدين' : 'e.g. Royal Abdeen Palace Gala'}" required autofocus>
              </div>
              <div class="form-field">
                <label for="plan-type">${w.kind}</label>
                <select id="plan-type" name="type">
                  <option value="wedding">${w.wedding}</option>
                  <option value="conference">${w.conference}</option>
                  <option value="other">${w.other}</option>
                </select>
              </div>
              <div class="form-field">
                <label for="plan-date">${w.date}</label>
                <input id="plan-date" type="date" name="date">
              </div>
            </div>
            <p class="form-error" role="alert" hidden></p>
            <div class="planner-create-modal-actions">
              <button class="button button-outline" type="button" data-action="planner-close-create">${isAr ? 'إلغاء' : 'Cancel'}</button>
              <button class="button" type="submit">${w.create}</button>
            </div>
          </form>
        </div>
      </div>
    </div>`;
  }
  view=view||'seating';
  if(view==='guests')return workspaceShell(plan,view,lang,esc,guestWorkspace(plan,lang,esc,guestSelected,guestForm));
  if(view==='ceremony'&&plan.type==='wedding')return workspaceShell(plan,view,lang,esc,ceremonyWorkspace(plan,lang,esc,ceremonyMode,ceremonySeat));
  if(view==='budget')return workspaceShell(plan,view,lang,esc,budgetWorkspace(plan,lang,esc));
  if(view==='tasks')return workspaceShell(plan,view,lang,esc,tasksWorkspace(plan,lang,esc,taskFilter));
  if(view==='timeline')return workspaceShell(plan,view,lang,esc,timelineWorkspace(plan,lang,esc));
  const assigned=plan.tables.reduce((total,table)=>total+table.assignments.filter(Boolean).length,0);
  const active=plan.tables.find(table=>table.id===selectedSeat?.tableId);
  const tabs=`<div class="plan-tabs-wrap"><nav class="plan-tabs" aria-label="${w.title}"><a href="#/plans/${plan.id}?view=overview" ${!['seating','3d','original','presentation'].includes(view)?'aria-current="page"':''}>${w.overview}</a><a href="#/plans/${plan.id}?view=seating" ${view==='seating'?'aria-current="page"':''}>${w.seating}</a><a href="#/plans/${plan.id}?view=3d" ${view==='3d'?'aria-current="page"':''}>${w.threeD}</a><a href="#/plans/${plan.id}?view=presentation" ${view==='presentation'?'aria-current="page"':''}>${w.presentation}</a>${plan.type==='wedding'?`<a href="#/plans/${plan.id}?view=original" ${view==='original'?'aria-current="page"':''}>${w.originalRoom}</a>`:''}</nav></div>`;
  const header=`<div class="planner-nav-bar"><a class="back-link" href="#/plans">← ${w.back}</a></div><section class="page-title planner-plan-header"><span class="planner-kicker">${w[plan.type]}</span><h1>${esc(plan.name)}</h1><p class="planner-plan-meta">${plan.date?'📅 '+esc(plan.date):''}${plan.access==='VIEW'?' · <span class="planner-badge">'+w.viewOnly+'</span>':''}</p>${view==='presentation'?'':`<div class="plan-actions"><button class="button button-outline" type="button" data-action="planner-print">↓ ${w.print}</button><button class="button button-outline" type="button" data-action="planner-csv">↓ ${w.csv}</button>${plan.access!=='VIEW'?`<button class="button button-outline" type="button" data-action="planner-undo" ${history?.undo?.length?'':'disabled'}>↶ ${w.undo}</button><button class="button button-outline" type="button" data-action="planner-redo" ${history?.redo?.length?'':'disabled'}>↷ ${w.redo}</button>`:''}</div>`}</section>${tabs}`;
  if(view==='presentation')return `${header}${presentationView(plan,w,esc,lang)}`;
  if(view==='3d'){
    const idea=suggestion||'saved',layout=idea==='saved'?plan:suggestedLayout;
    return `${header}<section class="room-3d" data-plan-preview><h2>${w.clientPreview}</h2><p>${w.clientPreviewHelp}</p><div class="room-suggestions"><h3>${w.suggestions}</h3><p>${w.suggestionsHelp}</p><div class="room-client-stops" role="group" aria-label="${w.suggestions}">${[['saved','savedLayout'],['wedding','weddingLayout'],['conference','conferenceLayout'],['mixed','mixedLayout']].map(([kind,label])=>`<button class="button button-outline" type="button" data-action="planner-suggestion" data-suggestion="${kind}" aria-pressed="${idea===kind}">${w[label]}</button>`).join('')}</div>${idea!=='saved'&&plan.access!=='VIEW'&&!plan.tables.length&&!plan.features.length?`<button class="button" type="button" data-action="planner-template" data-template="${idea}">${w.useSuggestion}</button>`:`<a class="button button-outline" href="#/plans/${plan.id}?view=seating">${w.editSeating}</a>`}</div><div class="room-client-stops" role="group" aria-label="${w.clientPreview}"><button class="button button-outline" type="button" data-scene-stop="overview" aria-pressed="true">${w.overviewStop}</button>${(layout.features||[]).some(item=>item.kind==='entrance')?`<button class="button button-outline" type="button" data-scene-stop="entrance" aria-pressed="false">${w.entranceStop}</button>`:''}${(layout.features||[]).some(item=>item.kind==='stage')?`<button class="button button-outline" type="button" data-scene-stop="stage" aria-pressed="false">${w.stageStop}</button>`:''}<button class="button button-outline" type="button" data-scene-stop="walk" aria-pressed="false">${w.walkStop}</button></div><div class="room-3d-controls">${layout.tables.length?`<label class="room-client-table-label">${w.chooseTable}<select data-scene-table><option value="">${w.chooseTableHint}</option>${layout.tables.map((table,index)=>`<option value="${index}">${esc(table.label)}</option>`).join('')}</select></label>`:''}${['golden','sunrise','midnight'].map(mode=>`<button class="button button-outline" type="button" data-scene-atmosphere="${mode}" aria-pressed="${mode==='golden'}">${w[mode]}</button>`).join('')}</div><div class="room-3d-canvas" role="img" aria-label="${w.clientPreview}"></div><aside class="room-3d-table-info" hidden aria-live="polite"></aside><p class="room-3d-status" role="status">${w.threeDLoading}</p></section>`;
  }
  if(view==='original'&&plan.type==='wedding')return `${header}${originalRoomSection(lang)}`;
  if(view!=='seating')return `${header}<fieldset class="plan-content" ${plan.access==='VIEW'?'disabled':''}>${planOverview(plan,w,esc,lang,inquiries)}</fieldset>${sharePanel(plan,members,w,esc)}`;
  const editing=plan.access!=='VIEW',ww=workspaceWords(lang);
  const floorTools=`<section class="planner-floor"><h2>${w.floorPlan}</h2><p class="fine-print">${w.floorPlanHelp}</p>${editing?`<label class="planner-upload ww-outline">${plan.floorPlan?w.replaceFloor:w.uploadFloor}<input id="plan-floor-upload" type="file" accept="image/jpeg,image/png,image/webp" hidden></label>`:''}${plan.floorPlan?`<div class="planner-inline">${editing?`<button class="ww-outline" type="button" data-action="planner-scale">${scaleMode?w.cancelScale:w.setScale}</button><button class="ww-outline" type="button" data-action="planner-remove-floor">${w.removeFloor}</button>`:''}</div>${scaleMode?`<p role="status">${scalePoints.length===0?w.scaleFirst:scalePoints.length===1?w.scaleSecond:w.scaleDistance}</p>`:plan.floorPlan.meters?`<p>${w.referenceScale}: ${plan.floorPlan.meters} m</p>`:''}${scalePoints.length===2?`<form id="plan-scale-form"><label>${w.scaleDistance}<input name="meters" type="number" min="0.1" max="1000" step="0.1" required></label><button class="ww-primary" type="submit">${w.saveScale}</button></form>`:''}`:''}<p id="floor-status" class="form-error" role="alert" hidden></p></section>`;
  const guestsPanel=`<section><h2>${w.guests} (${plan.guests.length})</h2>${editing?`<form id="plan-guest-form"><label for="guest-name">${w.guestName}</label><div class="planner-inline"><input id="guest-name" name="name" maxlength="100" required><button class="ww-primary" type="submit">${w.addGuest}</button></div></form>`:''}<p class="fine-print">${w.dragGuest}</p>${plan.guests.length?`<ul class="planner-guests">${plan.guests.map(g=>`<li><span ${editing&&g.rsvp!=='no'?`draggable="true" data-guest-id="${g.id}" title="${w.dragGuest}"`:''}>${esc(g.name)}</span></li>`).join('')}</ul>`:`<p>${w.noGuests}</p>`}<a class="ww-outline" href="#/plans/${plan.id}?view=guests">${ww.guests} →</a></section>`;
  const tablesPanel=`<section><h2>${w.tables} (${plan.tables.length})</h2>${editing?plan.tables.map(table=>tableEditor(table,w,esc)).join(''):plan.tables.map(table=>`<p>${esc(table.label)} · ${table.seats} ${w.seats}</p>`).join('')}</section><section><h2>${w.room} (${(plan.features||[]).length})</h2>${editing?(plan.features||[]).map(item=>featureEditor(item,w,esc)).join(''):(plan.features||[]).map(item=>`<p>${esc(item.label||w[item.kind])}</p>`).join('')}</section>`;
  const seatPanel=editing&&active?`<section class="planner-assign"><h2>${esc(active.label)} · ${w.seats} ${selectedSeat.index+1}</h2><label for="seat-guest">${w.guestName}</label><select id="seat-guest" data-table="${active.id}" data-index="${selectedSeat.index}"><option value="">${w.unassigned}</option>${plan.guests.filter(g=>g.rsvp!=='no').map(g=>`<option value="${g.id}" ${active.assignments[selectedSeat.index]===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></section>`:'';
  const panel=inspector==='floor'?floorTools:inspector==='tables'?tablesPanel:inspector==='guests'?guestsPanel:inspector==='seat'?seatPanel:'';
  const toolbar=`<div class="ww-canvas-toolbar" role="toolbar" aria-label="${ww.seating}">${editing?`<button type="button" data-action="planner-open-picker">＋ ${ww.add}</button>`:''}<button type="button" data-action="planner-show-inspector" data-panel="guests">☷ ${ww.list}</button><button type="button" data-action="planner-show-inspector" data-panel="floor">▧ ${ww.floor}</button><button type="button" data-action="planner-show-inspector" data-panel="tables">▦ ${ww.tableSettings}</button><button type="button" data-action="planner-toggle-grid">${ww.grid}</button>${editing?`<button type="button" data-action="planner-undo" ${history?.undo?.length?'':'disabled'} aria-label="${ww.undo}">↶</button><button type="button" data-action="planner-redo" ${history?.redo?.length?'':'disabled'} aria-label="${ww.redo}">↷</button>`:''}<span class="ww-toolbar-divider"></span><button type="button" data-action="planner-zoom-out" aria-label="${ww.zoomOut}">−</button><button type="button" data-action="planner-zoom-reset">${Math.round(zoom*100)}%</button><button type="button" data-action="planner-zoom-in" aria-label="${ww.zoomIn}">＋</button><button type="button" data-action="planner-print" aria-label="${ww.export}">↓</button></div>`;
  const content=`<div class="ww-editor"><div class="ww-floor-tabs"><span>▥</span><strong>${ww.floor}</strong><span class="ww-floor-tab-name">${ww.mainFloor}</span><span>${plan.access==='VIEW'?w.viewOnly:''}</span></div><div class="ww-canvas-surface ${gridVisible?'':'ww-no-grid'}"><div class="ww-tool-rail"><button type="button" data-action="planner-show-inspector" data-panel="floor" aria-label="${ww.floor}">✥</button><button type="button" data-action="planner-show-inspector" data-panel="tables" aria-label="${ww.tableSettings}">▦</button><button type="button" data-action="planner-show-inspector" data-panel="guests" aria-label="${ww.guests}">♙</button></div>${toolbar}<div class="ww-canvas-scroll"><div class="ww-canvas-layer" style="width:${Math.round(zoom*100)}%">${planBoard(plan,esc,lang)}</div></div><div class="ww-canvas-status">${plan.tables.length} ${w.tables} &nbsp;·&nbsp; ${assigned} ${w.assigned} &nbsp;·&nbsp; ${plan.guests.length} ${w.guests}</div>${panel?`<aside class="ww-inspector"><button class="ww-close" type="button" data-action="planner-close-inspector" aria-label="${ww.close}">×</button>${panel}</aside>`:''}<p id="planner-error" role="alert" class="form-error" hidden></p></div></div>${picker?tablePicker(lang,pickerCategory):''}`;
  return workspaceShell(plan,'seating',lang,esc,content);

}
